package com.slayqueen;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;

/**
 * Checks quests, skill levels and achievement diaries for task requirements.
 * Must be used on the client thread. Unknown names count as met, so bad data never
 * shows a false "missing requirement".
 */
@Singleton
public class AccountChecks implements TaskResolver.Account
{
	private final Client client;

	@Inject
	AccountChecks(Client client)
	{
		this.client = client;
	}

	@Override
	public int slayerLevel()
	{
		return client.getRealSkillLevel(Skill.SLAYER);
	}

	@Override
	public boolean met(TaskInfo.Requirement r)
	{
		if (r == null || r.getType() == null)
		{
			return true;
		}
		switch (r.getType())
		{
			case "QUEST":
				return questDone(r.getQuest(), r.isStarted());
			case "SKILL":
				return skillAtLeast(r.getSkill(), r.getLevel());
			case "DIARY":
				int varbit = diaryVarbit(r.getDiary(), r.getTier());
				return varbit < 0 || client.getVarbitValue(varbit) == 1;
			default:
				return true;
		}
	}

	private boolean questDone(String name, boolean startedIsEnough)
	{
		for (Quest q : Quest.values())
		{
			if (q.name().equals(name))
			{
				QuestState state = q.getState(client);
				return startedIsEnough ? state != QuestState.NOT_STARTED : state == QuestState.FINISHED;
			}
		}
		return true;
	}

	private boolean skillAtLeast(String name, int level)
	{
		for (Skill s : Skill.values())
		{
			if (s.name().equals(name))
			{
				return client.getRealSkillLevel(s) >= level;
			}
		}
		return true;
	}

	/**
	 * Varbit that is 1 when the diary tier is complete, or -1 if unknown.
	 */
	static int diaryVarbit(String diary, String tier)
	{
		String key = (diary == null ? "" : diary) + "_" + (tier == null ? "" : tier);
		switch (key)
		{
			case "ARDOUGNE_EASY": return VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE;
			case "ARDOUGNE_MEDIUM": return VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE;
			case "ARDOUGNE_HARD": return VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE;
			case "ARDOUGNE_ELITE": return VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE;
			case "DESERT_EASY": return VarbitID.DESERT_DIARY_EASY_COMPLETE;
			case "DESERT_MEDIUM": return VarbitID.DESERT_DIARY_MEDIUM_COMPLETE;
			case "DESERT_HARD": return VarbitID.DESERT_DIARY_HARD_COMPLETE;
			case "DESERT_ELITE": return VarbitID.DESERT_DIARY_ELITE_COMPLETE;
			case "FALADOR_EASY": return VarbitID.FALADOR_DIARY_EASY_COMPLETE;
			case "FALADOR_MEDIUM": return VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE;
			case "FALADOR_HARD": return VarbitID.FALADOR_DIARY_HARD_COMPLETE;
			case "FALADOR_ELITE": return VarbitID.FALADOR_DIARY_ELITE_COMPLETE;
			case "FREMENNIK_EASY": return VarbitID.FREMENNIK_DIARY_EASY_COMPLETE;
			case "FREMENNIK_MEDIUM": return VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE;
			case "FREMENNIK_HARD": return VarbitID.FREMENNIK_DIARY_HARD_COMPLETE;
			case "FREMENNIK_ELITE": return VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE;
			case "KANDARIN_EASY": return VarbitID.KANDARIN_DIARY_EASY_COMPLETE;
			case "KANDARIN_MEDIUM": return VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE;
			case "KANDARIN_HARD": return VarbitID.KANDARIN_DIARY_HARD_COMPLETE;
			case "KANDARIN_ELITE": return VarbitID.KANDARIN_DIARY_ELITE_COMPLETE;
			case "KARAMJA_ELITE": return VarbitID.KARAMJA_DIARY_ELITE_COMPLETE;
			case "KOUREND_EASY": return VarbitID.KOUREND_DIARY_EASY_COMPLETE;
			case "KOUREND_MEDIUM": return VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE;
			case "KOUREND_HARD": return VarbitID.KOUREND_DIARY_HARD_COMPLETE;
			case "KOUREND_ELITE": return VarbitID.KOUREND_DIARY_ELITE_COMPLETE;
			case "LUMBRIDGE_EASY": return VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE;
			case "LUMBRIDGE_MEDIUM": return VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE;
			case "LUMBRIDGE_HARD": return VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE;
			case "LUMBRIDGE_ELITE": return VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE;
			case "MORYTANIA_EASY": return VarbitID.MORYTANIA_DIARY_EASY_COMPLETE;
			case "MORYTANIA_MEDIUM": return VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE;
			case "MORYTANIA_HARD": return VarbitID.MORYTANIA_DIARY_HARD_COMPLETE;
			case "MORYTANIA_ELITE": return VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE;
			case "VARROCK_EASY": return VarbitID.VARROCK_DIARY_EASY_COMPLETE;
			case "VARROCK_MEDIUM": return VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE;
			case "VARROCK_HARD": return VarbitID.VARROCK_DIARY_HARD_COMPLETE;
			case "VARROCK_ELITE": return VarbitID.VARROCK_DIARY_ELITE_COMPLETE;
			case "WESTERN_EASY": return VarbitID.WESTERN_DIARY_EASY_COMPLETE;
			case "WESTERN_MEDIUM": return VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE;
			case "WESTERN_HARD": return VarbitID.WESTERN_DIARY_HARD_COMPLETE;
			case "WESTERN_ELITE": return VarbitID.WESTERN_DIARY_ELITE_COMPLETE;
			case "WILDERNESS_EASY": return VarbitID.WILDERNESS_DIARY_EASY_COMPLETE;
			case "WILDERNESS_MEDIUM": return VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE;
			case "WILDERNESS_HARD": return VarbitID.WILDERNESS_DIARY_HARD_COMPLETE;
			case "WILDERNESS_ELITE": return VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE;
			default: return -1;
		}
	}
}

package com.slayqueen;

import lombok.Builder;
import lombok.Value;

/**
 * The equipment bonuses the loadout scoring needs, copied from RuneLite's item stats
 * so the calculator can be tested without a client.
 */
@Value
@Builder
public class EquipStats
{
	/** EquipmentInventorySlot index. */
	int slot;
	boolean twoHanded;
	int astab;
	int aslash;
	int acrush;
	int amagic;
	int arange;
	int str;
	int rstr;
	float mdmg;
	int prayer;
	int aspeed;

	static final int SLOT_HEAD = 0;
	static final int SLOT_CAPE = 1;
	static final int SLOT_AMULET = 2;
	static final int SLOT_WEAPON = 3;
	static final int SLOT_BODY = 4;
	static final int SLOT_SHIELD = 5;
	static final int SLOT_LEGS = 7;
	static final int SLOT_GLOVES = 9;
	static final int SLOT_BOOTS = 10;
	static final int SLOT_RING = 12;
	static final int SLOT_AMMO = 13;

	static int slotIndex(String slot)
	{
		switch (slot)
		{
			case "HEAD":
				return SLOT_HEAD;
			case "CAPE":
				return SLOT_CAPE;
			case "AMULET":
				return SLOT_AMULET;
			case "WEAPON":
				return SLOT_WEAPON;
			case "BODY":
				return SLOT_BODY;
			case "SHIELD":
				return SLOT_SHIELD;
			case "LEGS":
				return SLOT_LEGS;
			case "GLOVES":
				return SLOT_GLOVES;
			case "BOOTS":
				return SLOT_BOOTS;
			case "RING":
				return SLOT_RING;
			case "AMMO":
				return SLOT_AMMO;
			default:
				return -1;
		}
	}

	/**
	 * Melee attack bonus that matters against a monster: its weakness if it is
	 * stab/slash/crush, otherwise the best of the three.
	 */
	int meleeAttack(String weakness)
	{
		if ("stab".equalsIgnoreCase(weakness))
		{
			return astab;
		}
		if ("slash".equalsIgnoreCase(weakness))
		{
			return aslash;
		}
		if ("crush".equalsIgnoreCase(weakness))
		{
			return acrush;
		}
		return Math.max(astab, Math.max(aslash, acrush));
	}

	/**
	 * How much this piece adds for a style. Damage bonuses are weighted above accuracy,
	 * the same way gear guides rank them. Prayer breaks ties.
	 */
	double armourScore(String style, String weakness)
	{
		switch (style)
		{
			case "RANGED":
				return rstr * 4.0 + arange + prayer * 0.1;
			case "MAGIC":
				return mdmg * 6.0 + amagic + prayer * 0.1;
			default:
				return str * 4.0 + meleeAttack(weakness) + prayer * 0.1;
		}
	}

	/**
	 * Rough damage-per-tick estimate for a weapon, used when no curated weapon is owned.
	 */
	double weaponScore(String style, String weakness)
	{
		int speed = aspeed > 0 ? aspeed : 4;
		switch (style)
		{
			case "RANGED":
				return arange <= 0 ? 0 : (arange + 64.0) * (rstr + 64.0) / speed;
			case "MAGIC":
				return amagic <= 0 ? 0 : (amagic + 64.0) * (1 + mdmg / 100.0) / speed;
			default:
				int att = meleeAttack(weakness);
				return (att <= 0 && str <= 0) ? 0 : (att + 64.0) * (str + 64.0) / speed;
		}
	}
}

package com.slayqueen;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.Data;

/**
 * Ranked gear lists (best first), loaded from gear.json.
 * styles: style -> slot -> item names.
 * special: task tag -> key -> item names, where key is a slot (e.g. AMULET)
 * or a style-specific weapon key (WEAPON_MELEE, WEAPON_RANGED, WEAPON_MAGIC).
 */
@Data
public class GearData
{
	private Map<String, Map<String, List<String>>> styles;
	private Map<String, Map<String, List<String>>> special;
	/** Ancient Magicks capable weapons and barrage gear, plus CHINCHOMPA. */
	private Map<String, List<String>> aoe;

	List<String> aoe(String key)
	{
		List<String> list = aoe == null ? null : aoe.get(key);
		return list == null ? Collections.emptyList() : list;
	}

	List<String> generic(String style, String slot)
	{
		Map<String, List<String>> slots = styles == null ? null : styles.get(style);
		List<String> list = slots == null ? null : slots.get(slot);
		return list == null ? Collections.emptyList() : list;
	}

	List<String> special(String tag, String key)
	{
		Map<String, List<String>> keys = special == null ? null : special.get(tag);
		List<String> list = keys == null ? null : keys.get(key);
		return list == null ? Collections.emptyList() : list;
	}
}

package com.slayqueen;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.http.api.item.ItemPrice;

/**
 * Game sprites and item icons for the overlay and panel. Sprite lookups must happen on the client thread.
 */
@Singleton
public class Icons
{
	static final int SIZE = 16;
	private static final int NO_ITEM = -1;

	private final SpriteManager spriteManager;
	private final ItemManager itemManager;
	private final Map<Integer, BufferedImage> sprites = new HashMap<>();
	private final Map<Integer, BufferedImage> items = new ConcurrentHashMap<>();
	private final Set<Integer> requested = ConcurrentHashMap.newKeySet();
	private final Map<String, Integer> idsByName = new ConcurrentHashMap<>();

	@Inject
	Icons(SpriteManager spriteManager, ItemManager itemManager)
	{
		this.spriteManager = spriteManager;
		this.itemManager = itemManager;
	}

	BufferedImage sprite(int spriteId)
	{
		BufferedImage cached = sprites.get(spriteId);
		if (cached != null)
		{
			return cached;
		}
		BufferedImage img = spriteManager.getSprite(spriteId, 0);
		if (img == null)
		{
			return null;
		}
		BufferedImage scaled = ImageUtil.resizeImage(img, SIZE, SIZE, true);
		sprites.put(spriteId, scaled);
		return scaled;
	}

	/**
	 * Small item icon for the overlay. Returns null until the image has loaded.
	 */
	BufferedImage item(int itemId)
	{
		BufferedImage cached = items.get(itemId);
		if (cached != null)
		{
			return cached;
		}
		if (!requested.add(itemId))
		{
			return null;
		}
		net.runelite.client.util.AsyncBufferedImage img = itemManager.getImage(itemId);
		img.onLoaded(() -> items.put(itemId, ImageUtil.resizeImage(img, SIZE + 2, SIZE, true)));
		return null;
	}

	/**
	 * Item id for a name, for items the player doesn't own yet. Only tradeable items can be found.
	 */
	int idForName(String name)
	{
		Integer cached = idsByName.get(name);
		if (cached != null)
		{
			return cached;
		}
		List<ItemPrice> results = itemManager.search(name);
		if (results.isEmpty())
		{
			// Prices may not have loaded yet; try again later rather than caching a miss
			return NO_ITEM;
		}
		int id = NO_ITEM;
		for (ItemPrice p : results)
		{
			// Exact name only, so "Bonecrusher" doesn't show the Bonecrusher necklace
			if (p.getName().equalsIgnoreCase(name))
			{
				id = p.getId();
				break;
			}
		}
		idsByName.put(name, id);
		return id;
	}

	BufferedImage itemByName(String name)
	{
		int id = idForName(name);
		return id == NO_ITEM ? null : item(id);
	}

	BufferedImage cannon()
	{
		return item(ItemID.MCANNONBALL);
	}

	BufferedImage aoe(String aoe)
	{
		if ("CHINCHOMPA".equals(aoe))
		{
			return item(ItemID.CHINCHOMPA_BLACK);
		}
		return sprite("BURST".equals(aoe) ? SpriteID.Magicon2.ICE_BURST : SpriteID.Magicon2.ICE_BARRAGE);
	}

	/**
	 * Rune icon for an elemental weakness, or null.
	 */
	BufferedImage weakness(String weakness)
	{
		if (weakness == null)
		{
			return null;
		}
		switch (weakness.toLowerCase(java.util.Locale.ROOT))
		{
			case "air":
				return item(ItemID.AIRRUNE);
			case "water":
				return item(ItemID.WATERRUNE);
			case "earth":
				return item(ItemID.EARTHRUNE);
			case "fire":
				return item(ItemID.FIRERUNE);
			default:
				return null;
		}
	}

	BufferedImage style(String style)
	{
		switch (LoadoutCalculator.baseStyle(style == null ? "MELEE" : style))
		{
			case "RANGED":
				return sprite(SpriteID.Staticons.RANGED);
			case "MAGIC":
				return sprite(SpriteID.Staticons.MAGIC);
			default:
				return sprite(SpriteID.Staticons.ATTACK);
		}
	}
}

package com.slayqueen;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Outlines the recommended gear and items in the bank (and optionally the inventory).
 */
public class ItemHighlightOverlay extends WidgetItemOverlay
{
	private final SlayQueenPlugin plugin;
	private final SlayQueenConfig config;
	private final ItemManager itemManager;

	@Inject
	ItemHighlightOverlay(SlayQueenPlugin plugin, SlayQueenConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnBank();
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		boolean inBank = widgetItem.getWidget() != null
			&& (widgetItem.getWidget().getId() >>> 16) == InterfaceID.BANKMAIN;
		if (inBank ? !config.highlightBank() : !config.highlightInventory())
		{
			return;
		}
		if (!plugin.getHighlightIds().contains(itemId))
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), config.highlightColor());
		graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
	}
}

package com.slayqueen;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.IntFunction;
import lombok.Value;

/**
 * Picks the best gear a player owns for a task. Pure logic, no client access,
 * so it can be unit tested.
 *
 * Order of preference for each slot:
 * 1. task-specific gear (salve amulet for undead, leaf-bladed weapons, dragonhunter, ...)
 * 2. slayer helmet / black mask for the head slot
 * 3. curated weapon list for the weapon slot
 * 4. the owned item with the best real equipment bonuses for the style and the monster's weakness
 */
public class LoadoutCalculator
{
	/** Magic with Ancient Magicks (burst/barrage). Weapon must be able to cast Ancients. */
	static final String AOE_MAGIC = "AOE_MAGIC";
	/** Ranged with chinchompas. */
	static final String CHINCHOMPA = "CHINCHOMPA";

	static final String[] SLOTS = {
		"HEAD", "CAPE", "AMULET", "AMMO", "WEAPON", "BODY", "SHIELD", "LEGS", "GLOVES", "BOOTS", "RING"
	};

	private static final String[] UNUSABLE_SUFFIXES = {"(uncharged)", "(inactive)", "(broken)", "(empty)", "(deadman)", " (u)"};

	@Value
	public static class Pick
	{
		String name;
		int itemId;
	}

	@Value
	public static class NeedStatus
	{
		TaskInfo.ItemNeed need;
		/** The owned item that satisfies this need, or null if missing. */
		Pick owned;
	}

	@Value
	public static class Loadout
	{
		String style;
		Map<String, Pick> gear;
		List<NeedStatus> required;
		List<NeedStatus> recommended;
		List<NeedStatus> loot;
		List<NeedStatus> supplies;
		/** Teleport items to reach the task (fairy rings etc. are shown as text, not here). */
		List<NeedStatus> travel;
	}

	/**
	 * Owned items keyed by lower-case item name.
	 */
	private final Map<String, Pick> owned;

	public LoadoutCalculator(Map<String, Pick> ownedByLowerName)
	{
		this.owned = ownedByLowerName;
	}

	/**
	 * Tags where only special gear can damage the monster, so there is no generic fallback
	 * (e.g. kurask/turoth need leaf-bladed melee, broad ammo or Magic Dart).
	 */
	private static final String RESTRICTIVE_TAG = "leafy";

	/**
	 * @param stats equipment stats for an item id, or null when it isn't equipable/unknown
	 */
	public Loadout calculate(TaskInfo task, String style, GearData gear, IntFunction<EquipStats> stats)
	{
		// An AoE setup is useless without a weapon that can cast Ancients (or chinchompas),
		// so fall back to the task's normal style.
		if (AOE_MAGIC.equals(style) && findOwned(gear.aoe("WEAPON")) == null
			|| CHINCHOMPA.equals(style) && findOwned(gear.aoe("CHINCHOMPA")) == null)
		{
			List<String> styles = task.getStyles();
			String fallback = styles == null || styles.isEmpty() ? "MELEE" : styles.get(0);
			return calculate(task, fallback, gear, stats);
		}

		String weakness = task.getWeakness();
		Map<String, Pick> picks = new LinkedHashMap<>();
		String gearStyle = baseStyle(style);

		// Weapon first, because ammo and the shield depend on it
		Pick weapon;
		if (AOE_MAGIC.equals(style))
		{
			weapon = findOwned(gear.aoe("WEAPON"));
		}
		else if (CHINCHOMPA.equals(style))
		{
			weapon = findOwned(gear.aoe("CHINCHOMPA"));
		}
		else
		{
			weapon = pickWeapon(task, style, weakness, gear, stats);
		}
		if (weapon != null)
		{
			picks.put("WEAPON", weapon);
		}

		// Salve amulet for undead tasks
		Pick salve = task.tagsOrEmpty().contains("undead") ? pickSalve(gear, gearStyle) : null;

		for (String slot : SLOTS)
		{
			if ("WEAPON".equals(slot))
			{
				continue;
			}
			Pick pick;
			if ("AMMO".equals(slot))
			{
				pick = "RANGED".equals(style) ? pickAmmo(task, weapon, gear, stats) : null;
			}
			else if ("AMULET".equals(slot) && salve != null)
			{
				pick = salve;
			}
			else
			{
				// Always suggest the best slayer helmet/black mask owned, even alongside a salve
				pick = pickArmour(task, slot, style, gearStyle, weakness, gear, stats, true);
			}
			if (pick != null)
			{
				picks.put(slot, pick);
			}
		}

		if (weapon != null)
		{
			EquipStats ws = stats.apply(weapon.getItemId());
			if (ws != null && ws.isTwoHanded())
			{
				picks.remove("SHIELD");
			}
		}

		// Keep the display in equipment order
		Map<String, Pick> ordered = new LinkedHashMap<>();
		for (String slot : SLOTS)
		{
			if (picks.containsKey(slot))
			{
				ordered.put(slot, picks.get(slot));
			}
		}

		return new Loadout(style, ordered,
			statuses(task.getRequiredItems()),
			statuses(task.getRecommendedItems()),
			statuses(task.getLootItems()),
			statuses(task.getSupplies()),
			statuses(travelItems(task)));
	}

	/**
	 * The plain style used for armour scoring and curated lists.
	 */
	static String baseStyle(String style)
	{
		if (AOE_MAGIC.equals(style))
		{
			return "MAGIC";
		}
		if (CHINCHOMPA.equals(style))
		{
			return "RANGED";
		}
		return style;
	}

	private List<String> specialFor(TaskInfo task, GearData gear, String key)
	{
		List<String> out = new ArrayList<>();
		for (String tag : task.tagsOrEmpty())
		{
			out.addAll(gear.special(tag, key));
		}
		return out;
	}

	/**
	 * Salve amulet for undead tasks. Only the imbued versions help ranged and magic.
	 */
	private Pick pickSalve(GearData gear, String style)
	{
		List<String> salves = new ArrayList<>();
		for (String name : gear.special("undead", "AMULET"))
		{
			if ("MELEE".equals(style) || name.toLowerCase(Locale.ROOT).contains("i)"))
			{
				salves.add(name);
			}
		}
		return findOwned(salves);
	}

	private Pick pickWeapon(TaskInfo task, String style, String weakness, GearData gear, IntFunction<EquipStats> stats)
	{
		List<String> special = specialFor(task, gear, "WEAPON_" + style);
		special.addAll(specialFor(task, gear, "WEAPON"));
		Pick pick = findOwned(special);
		if (pick != null)
		{
			return pick;
		}
		if (task.tagsOrEmpty().contains(RESTRICTIVE_TAG))
		{
			// Nothing else can damage these; the missing required item is shown instead
			return null;
		}

		pick = findOwned(gear.generic(style, "WEAPON"));
		if (pick != null)
		{
			return pick;
		}
		return bestByStats(EquipStats.SLOT_WEAPON, stats, s -> s.weaponScore(style, weakness));
	}

	private Pick pickArmour(TaskInfo task, String slot, String style, String gearStyle, String weakness,
		GearData gear, IntFunction<EquipStats> stats, boolean allowSlayerHead)
	{
		// Task-specific armour (e.g. dragonfire shields, Efaritay's aid) is melee-oriented
		if ("MELEE".equals(gearStyle))
		{
			Pick special = findOwned(specialFor(task, gear, slot));
			if (special != null)
			{
				return special;
			}
		}

		List<String> curated = gear.generic(gearStyle, slot);
		if ("HEAD".equals(slot) && allowSlayerHead)
		{
			// On task, a slayer helmet or black mask beats any other helmet.
			// Only the imbued versions boost ranged and magic.
			List<String> slayerHeads = new ArrayList<>();
			for (String name : curated)
			{
				String lower = name.toLowerCase(Locale.ROOT);
				boolean slayerHead = lower.contains("slayer helmet") || lower.contains("black mask");
				if (slayerHead && ("MELEE".equals(gearStyle) || lower.contains("(i)")))
				{
					slayerHeads.add(name);
				}
			}
			Pick head = findOwned(slayerHeads);
			if (head != null)
			{
				return head;
			}
		}

		if (AOE_MAGIC.equals(style))
		{
			Pick aoe = findOwned(gear.aoe(slot));
			if (aoe != null)
			{
				return aoe;
			}
		}

		// Curated rankings first (they account for set effects), then real stats to fill gaps
		Pick pick = findOwned(withoutSlayerHeads(curated));
		if (pick != null)
		{
			return pick;
		}
		return bestByStats(EquipStats.slotIndex(slot), stats, s -> s.armourScore(gearStyle, weakness));
	}

	private static List<String> withoutSlayerHeads(List<String> names)
	{
		List<String> out = new ArrayList<>();
		for (String n : names)
		{
			String lower = n.toLowerCase(Locale.ROOT);
			if (!lower.contains("slayer helmet") && !lower.contains("black mask"))
			{
				out.add(n);
			}
		}
		return out;
	}

	private Pick pickAmmo(TaskInfo task, Pick weapon, GearData gear, IntFunction<EquipStats> stats)
	{
		String ammoType = weapon == null ? null : ammoTypeFor(weapon.getName());
		if (ammoType == null)
		{
			return null;
		}
		String weaponName = weapon.getName().toLowerCase(Locale.ROOT);

		// Task-specific ammo (e.g. broad bolts for kurask) if it fits the weapon
		for (String name : specialFor(task, gear, "AMMO"))
		{
			if (name.toLowerCase(Locale.ROOT).contains(ammoType))
			{
				Pick p = findOwned(List.of(name));
				if (p != null)
				{
					return p;
				}
			}
		}
		if (task.tagsOrEmpty().contains(RESTRICTIVE_TAG))
		{
			return null;
		}

		Pick best = null;
		double bestScore = 0;
		for (Pick p : owned.values())
		{
			String name = p.getName().toLowerCase(Locale.ROOT);
			if (!name.contains(ammoType) || !usable(p.getName()) || !canFire(weaponName, name))
			{
				continue;
			}
			EquipStats s = stats.apply(p.getItemId());
			if (s == null || s.getSlot() != EquipStats.SLOT_AMMO)
			{
				continue;
			}
			double score = s.getRstr() * 4.0 + s.getArange() + 1;
			if (score > bestScore)
			{
				bestScore = score;
				best = p;
			}
		}
		return best;
	}

	/**
	 * Dragon arrows and dragon bolts need a high-tier bow or crossbow.
	 */
	static boolean canFire(String weapon, String ammo)
	{
		if (ammo.startsWith("dragon arrow"))
		{
			return weapon.contains("twisted bow") || weapon.contains("dark bow") || weapon.contains("venator bow");
		}
		if (ammo.startsWith("dragon bolts") || ammo.startsWith("dragonstone") || ammo.startsWith("onyx") || ammo.startsWith("ruby dragon")
			|| ammo.startsWith("diamond dragon") || ammo.startsWith("opal dragon") || ammo.startsWith("emerald dragon"))
		{
			return weapon.contains("dragon") || weapon.contains("armadyl") || weapon.contains("zaryte");
		}
		return true;
	}

	/**
	 * Which ammo a ranged weapon fires, as a word found in the ammo's name, or null if it needs none
	 * (or uses something the plugin can't match, like ether or special bolts).
	 */
	static String ammoTypeFor(String weaponName)
	{
		String w = weaponName.toLowerCase(Locale.ROOT);
		if (w.contains("craw's") || w.contains("webweaver") || w.contains("sunlight") || w.contains("hunters'"))
		{
			return null;
		}
		if (w.contains("ballista"))
		{
			return "javelin";
		}
		if (w.contains("karil"))
		{
			return "bolt rack";
		}
		if (w.contains("crossbow"))
		{
			return "bolt";
		}
		if (w.contains("atlatl"))
		{
			return "atlatl dart";
		}
		if (w.contains("faerdhinen") || w.contains("crystal bow") || w.contains("blowpipe"))
		{
			return null;
		}
		if (w.contains("bow"))
		{
			return "arrow";
		}
		return null;
	}

	private interface Scorer
	{
		double score(EquipStats s);
	}

	private Pick bestByStats(int slotIndex, IntFunction<EquipStats> stats, Scorer scorer)
	{
		if (slotIndex < 0)
		{
			return null;
		}
		Pick best = null;
		double bestScore = 0;
		for (Pick p : owned.values())
		{
			if (!usable(p.getName()))
			{
				continue;
			}
			EquipStats s = stats.apply(p.getItemId());
			if (s == null || s.getSlot() != slotIndex)
			{
				continue;
			}
			double score = scorer.score(s);
			if (score > bestScore)
			{
				bestScore = score;
				best = p;
			}
		}
		return best;
	}

	/**
	 * Teleports that are items you carry (not fairy rings, spirit trees or spells).
	 */
	static List<TaskInfo.ItemNeed> travelItems(TaskInfo task)
	{
		List<TaskInfo.ItemNeed> out = new ArrayList<>();
		for (TaskInfo.Teleport t : TaskInfo.orEmpty(task.getTeleports()))
		{
			String item = t.getItem();
			if (item == null || item.equals("Fairy ring") || item.equals("Spirit tree") || item.equals("Spellbook") || item.equals("Minigame teleport"))
			{
				continue;
			}
			TaskInfo.ItemNeed n = new TaskInfo.ItemNeed();
			n.setName(item);
			n.setAlternatives(t.getAlternatives());
			n.setReason(t.getDestination());
			out.add(n);
		}
		return out;
	}

	private List<NeedStatus> statuses(List<TaskInfo.ItemNeed> needs)
	{
		List<NeedStatus> out = new ArrayList<>();
		for (TaskInfo.ItemNeed need : TaskInfo.orEmpty(needs))
		{
			out.add(new NeedStatus(need, findOwned(need.allNames())));
		}
		return out;
	}

	/**
	 * First candidate (in order) that the player owns. A candidate matches an owned item with
	 * the same name, or a variant of it such as "Slayer helmet (i)" or "Salve amulet(ei)".
	 * Uncharged/inactive versions are skipped.
	 */
	Pick findOwned(List<String> candidates)
	{
		for (String candidate : candidates)
		{
			if (candidate == null || candidate.isEmpty())
			{
				continue;
			}
			String c = candidate.toLowerCase(Locale.ROOT);
			Pick exact = owned.get(c);
			if (exact != null && usable(exact.getName()))
			{
				return exact;
			}
			for (Map.Entry<String, Pick> e : owned.entrySet())
			{
				if (isVariant(e.getKey(), c) && usable(e.getKey()))
				{
					return e.getValue();
				}
			}
		}
		return null;
	}

	static boolean isVariant(String ownedName, String candidate)
	{
		if (!ownedName.startsWith(candidate) || ownedName.length() == candidate.length())
		{
			return false;
		}
		char next = ownedName.charAt(candidate.length());
		return next == ' ' || next == '(';
	}

	static boolean usable(String name)
	{
		String lower = name.toLowerCase(Locale.ROOT);
		for (String suffix : UNUSABLE_SUFFIXES)
		{
			if (lower.contains(suffix))
			{
				return false;
			}
		}
		return !lower.startsWith("uncharged ");
	}
}

