@Slf4j
@PluginDescriptor(
	name = "Slay Queen",
	description = "Shows what to bring for your slayer task based on the gear you own",
	tags = {"slayer", "task", "gear", "loadout", "bis", "cannon"}
)
@PluginDependency(BankTagsPlugin.class)
public class SlayQueenPlugin extends Plugin
{
	private static final String BANK_KEY = "bankItems";
	private static final int NEW_TASK_SECONDS = 90;
	private static final int BOSS_TASK_ID = 98;
	static final String BANK_TAG = "slayqueen";
	private static final String LAST_TASK_KEY = "lastTask";
	/** Set when a new task is assigned, cleared the first time the bank is closed afterwards. */
	private static final String NEEDS_PREP_KEY = "needsPrep";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private Gson gson;

	@Inject
	private SlayQueenConfig config;

	@Inject
	private TagManager tagManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private Icons icons;

	@Inject
	private AccountChecks accountChecks;

	private final TaskResolver resolver = new TaskResolver();

	private SlayQueenPanel panel;
	private NavigationButton navButton;

	@Inject
	private SlayQueenOverlay overlay;

	@Inject
	private ItemHighlightOverlay highlightOverlay;

	private Map<String, TaskInfo> tasksByKey = Collections.emptyMap();
	private GearData gearData;

	private int[] bankItemIds = new int[0];
	/** Owned item ids for every owned item name (lower case), so all doses/variants get highlighted. */
	private Map<String, Set<Integer>> ownedIdsByName = Collections.emptyMap();
	private boolean dirty;
	private boolean taskDirty;
	private boolean savingBank;

	/** The task's general advice, as loaded. */
	private volatile TaskInfo currentTask;
	/** The advice adapted to this player (Konar area, Wilderness, diaries); what gets displayed. */
	@Getter
	private volatile TaskInfo displayTask;
	@Getter
	private volatile List<TaskInfo.Requirement> unmetRequirements = Collections.emptyList();
	@Getter
	private volatile List<String> waivedItems = Collections.emptyList();
	@Getter
	private volatile String currentTaskName;
	@Getter
	private volatile String currentLocation;
	@Getter
	private volatile int remaining;
	@Getter
	private volatile LoadoutCalculator.Loadout loadout;
	@Getter
	private volatile Set<Integer> highlightIds = Collections.emptySet();

	@Getter
	private volatile boolean bankOpen;
	private volatile boolean needsPrep;
	private volatile Instant showUntil = Instant.EPOCH;

	@Provides
	SlayQueenConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayQueenConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadData();
		overlayManager.add(overlay);
		overlayManager.add(highlightOverlay);
		panel = new SlayQueenPanel();
		navButton = NavigationButton.builder()
			.tooltip("Slay Queen")
			.icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		// Typing "tag:slayqueen" in the bank search shows only the loadout items
		tagManager.registerTag(BANK_TAG, itemId -> highlightIds.contains(itemId));
		clientThread.invokeLater(() ->
		{
			loadBankFromProfile();
			updateTask();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(highlightOverlay);
		tagManager.unregisterTag(BANK_TAG);
		clientToolbar.removeNavigation(navButton);
		panel = null;
		bankItemIds = new int[0];
		ownedIdsByName = Collections.emptyMap();
		dirty = false;
		taskDirty = false;
		currentTask = null;
		currentTaskName = null;
		loadout = null;
		highlightIds = Collections.emptySet();
	}

	private void loadData()
	{
		TaskInfo[] tasks = readJson("tasks.json", TaskInfo[].class);
		Map<String, TaskInfo> byKey = new HashMap<>();
		if (tasks != null)
		{
			for (TaskInfo t : tasks)
			{
				byKey.put(key(t.getName()), t);
			}
		}
		tasksByKey = byKey;
		gearData = readJson("gear.json", GearData.class);
	}

	private <T> T readJson(String file, Class<T> type)
	{
		try (InputStream in = SlayQueenPlugin.class.getResourceAsStream(file))
		{
			if (in == null)
			{
				log.warn("Missing resource {}", file);
				return null;
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				return gson.fromJson(reader, type);
			}
		}
		catch (Exception e)
		{
			log.warn("Unable to read {}", file, e);
			return null;
		}
	}

	/**
	 * Normalises a task name so "The Alchemical Hydra" and "ALCHEMICAL HYDRA" match.
	 */
	static String key(String name)
	{
		if (name == null)
		{
			return "";
		}
		String k = name.trim().toLowerCase(Locale.ROOT);
		return k.startsWith("the ") ? k.substring(4) : k;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			taskDirty = true;
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			currentTask = null;
			currentTaskName = null;
			currentLocation = null;
			remaining = 0;
			loadout = null;
			highlightIds = Collections.emptySet();
			refreshPanel();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// Saving the bank for a new profile fires this event before the value is written;
		// the bank we just read is already correct, so don't reload it.
		if (savingBank)
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			loadBankFromProfile();
			dirty = true;
		});
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Batch all changes into at most one recalculation per tick
		if (taskDirty)
		{
			taskDirty = false;
			updateTask();
		}
		else if (dirty)
		{
			dirty = false;
			recalculate();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varp = event.getVarpId();
		if (varp == VarPlayerID.SLAYER_COUNT || varp == VarPlayerID.SLAYER_TARGET || varp == VarPlayerID.SLAYER_AREA
			|| event.getVarbitId() == VarbitID.SLAYER_TARGET_BOSSID)
		{
			taskDirty = true;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.BANK)
		{
			int[] ids = itemIds(event.getItemContainer());
			if (!java.util.Arrays.equals(ids, bankItemIds))
			{
				bankItemIds = ids;
				saveBankToProfile();
				dirty = true;
			}
		}
		else if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			dirty = true;
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = true;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankOpen = false;
			if (needsPrep)
			{
				// Geared up for the task; the "new task only" overlay has done its job
				needsPrep = false;
				configManager.unsetRSProfileConfiguration(SlayQueenConfig.GROUP, NEEDS_PREP_KEY);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SlayQueenConfig.GROUP.equals(event.getGroup())
			&& !BANK_KEY.equals(event.getKey()) && !LAST_TASK_KEY.equals(event.getKey())
			&& !NEEDS_PREP_KEY.equals(event.getKey()))
		{
			clientThread.invokeLater(this::recalculate);
		}
	}

	boolean shouldShowOverlay()
	{
		if (currentTaskName == null)
		{
			return false;
		}
		switch (config.overlayMode())
		{
			case ALWAYS:
				return true;
			case BANK_ONLY:
				return bankOpen;
			case NEW_TASK_ONLY:
				return Instant.now().isBefore(showUntil);
			case NEW_TASK_UNTIL_BANK_CLOSE:
				return needsPrep;
			default:
				return bankOpen || Instant.now().isBefore(showUntil);
		}
	}

	private void updateTask()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		int amount = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		String name = amount > 0 ? lookupTaskName() : null;
		String location = amount > 0 ? lookupArea() : null;

		// Only pop the overlay up for a genuinely new task, not on every login/world hop
		boolean changed = false;
		if (name != null)
		{
			String taskKey = name + ":" + client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
			String last = configManager.getRSProfileConfiguration(SlayQueenConfig.GROUP, LAST_TASK_KEY);
			if (!taskKey.equals(last))
			{
				changed = true;
				configManager.setRSProfileConfiguration(SlayQueenConfig.GROUP, LAST_TASK_KEY, taskKey);
				configManager.setRSProfileConfiguration(SlayQueenConfig.GROUP, NEEDS_PREP_KEY, true);
			}
		}
		remaining = amount;
		currentTaskName = name;
		currentLocation = location;
		currentTask = name == null ? null : tasksByKey.get(key(name));
		if (changed)
		{
			needsPrep = true;
			showUntil = Instant.now().plusSeconds(NEW_TASK_SECONDS);
		}
		recalculate();
	}

	/**
	 * Reads the current task name from the game's slayer task table, the same way
	 * RuneLite's Slayer plugin does.
	 */
	private String lookupTaskName()
	{
		int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		int taskRow;
		if (taskId == BOSS_TASK_ID)
		{
			List<Integer> bossRows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID,
				DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
			if (bossRows.isEmpty())
			{
				return null;
			}
			taskRow = (Integer) client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
		}
		else
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
			if (rows.isEmpty())
			{
				return null;
			}
			taskRow = rows.get(0);
		}
		return (String) client.getDBTableField(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
	}

	private String lookupArea()
	{
		int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		if (areaId <= 0)
		{
			return null;
		}
		List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
		if (rows.isEmpty())
		{
			return null;
		}
		return (String) client.getDBTableField(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0)[0];
	}

	/**
	 * Rebuilds the loadout from everything the player owns. Must run on the client thread
	 * because it reads item definitions.
	 */
	private void recalculate()
	{
		if (panel == null)
		{
			// Plugin is shut down
			return;
		}
		TaskInfo base = currentTask;
		if (base == null || gearData == null)
		{
			displayTask = null;
			unmetRequirements = Collections.emptyList();
			waivedItems = Collections.emptyList();
			loadout = null;
			highlightIds = Collections.emptySet();
			refreshPanel();
			return;
		}

		TaskResolver.Resolved resolved = resolver.resolve(base, currentLocation, isWildernessTask(), accountChecks);
		TaskInfo task = resolved.getTask();
		displayTask = task;
		unmetRequirements = resolved.getUnmet();
		waivedItems = resolved.getWaived();

		Map<String, LoadoutCalculator.Pick> owned = new HashMap<>();
		Map<String, Set<Integer>> allIds = new HashMap<>();
		addOwned(owned, allIds, bankItemIds);
		addOwned(owned, allIds, itemIds(client.getItemContainer(InventoryID.INV)));
		addOwned(owned, allIds, itemIds(client.getItemContainer(InventoryID.WORN)));
		ownedIdsByName = allIds;

		LoadoutCalculator.Loadout result = new LoadoutCalculator(owned)
			.calculate(task, chooseStyle(task), gearData, this::equipStats);

		// Highlight every id with a picked name, so all potion doses and duplicates light up
		Set<Integer> ids = new HashSet<>();
		result.getGear().values().forEach(p -> addIds(ids, allIds, p));
		for (List<LoadoutCalculator.NeedStatus> list : List.of(result.getRequired(), result.getRecommended(), result.getLoot(),
			result.getSupplies(), result.getTravel()))
		{
			for (LoadoutCalculator.NeedStatus s : list)
			{
				if (s.getOwned() != null)
				{
					addIds(ids, allIds, s.getOwned());
				}
			}
		}

		loadout = result;
		highlightIds = ids;
		refreshPanel();
	}

	private java.awt.image.BufferedImage itemImageForWeakness(String weakness)
	{
		if (weakness == null)
		{
			return null;
		}
		switch (weakness.toLowerCase(Locale.ROOT))
		{
			case "air":
				return itemManager.getImage(net.runelite.api.gameval.ItemID.AIRRUNE);
			case "water":
				return itemManager.getImage(net.runelite.api.gameval.ItemID.WATERRUNE);
			case "earth":
				return itemManager.getImage(net.runelite.api.gameval.ItemID.EARTHRUNE);
			case "fire":
				return itemManager.getImage(net.runelite.api.gameval.ItemID.FIRERUNE);
			default:
				return null;
		}
	}

	private void refreshPanel()
	{
		SlayQueenPanel p = panel;
		if (p == null)
		{
			return;
		}
		TaskInfo task = displayTask;
		LoadoutCalculator.Loadout l = loadout;
		SlayQueenPanel.View view = SlayQueenPanel.View.builder()
			.unmet(unmetRequirements)
			.waived(waivedItems)
			.taskName(currentTaskName)
			.location(currentLocation)
			.remaining(remaining)
			.task(task)
			.loadout(l)
			.theme(config.theme())
			.cannonIcon(itemManager.getImage(net.runelite.api.gameval.ItemID.MCANNONBALL))
			.aoeIcon(task == null ? null : icons.aoe(task.getAoe() == null ? "BARRAGE" : task.getAoe()))
			.styleIcon(icons.style(l == null ? null : l.getStyle()))
			.weaknessIcon(task == null ? null : itemImageForWeakness(task.getWeakness()))
			.itemImage(itemManager::getImage)
			.itemImageByName(name ->
			{
				int id = icons.idForName(name);
				return id < 0 ? null : itemManager.getImage(id);
			})
			.build();
		SwingUtilities.invokeLater(() -> p.display(view));
	}


	/**
	 * Slayer master varbit value for Krystilia (same constant as RuneLite's Slayer plugin).
	 */
	static final int KRYSTILIA = 7;

	private boolean isWildernessTask()
	{
		return client.getVarbitValue(VarbitID.SLAYER_MASTER) == KRYSTILIA;
	}

	private String chooseStyle(TaskInfo task)
	{
		SlayQueenConfig.StyleChoice choice = config.style();
		if (choice != SlayQueenConfig.StyleChoice.AUTO)
		{
			return choice.name();
		}
		if (config.preferAoe() && task.aoeStandard())
		{
			return "CHINCHOMPA".equals(task.getAoe()) ? LoadoutCalculator.CHINCHOMPA : LoadoutCalculator.AOE_MAGIC;
		}
		List<String> styles = task.getStyles();
		return styles == null || styles.isEmpty() ? "MELEE" : styles.get(0);
	}

	/**
	 * Equipment bonuses from RuneLite's item stats, or null if the item can't be equipped.
	 */
	private EquipStats equipStats(int itemId)
	{
		ItemStats stats = itemManager.getItemStats(itemId);
		if (stats == null || !stats.isEquipable() || stats.getEquipment() == null)
		{
			return null;
		}
		ItemEquipmentStats e = stats.getEquipment();
		return EquipStats.builder()
			.slot(e.getSlot())
			.twoHanded(e.isTwoHanded())
			.astab(e.getAstab())
			.aslash(e.getAslash())
			.acrush(e.getAcrush())
			.amagic(e.getAmagic())
			.arange(e.getArange())
			.str(e.getStr())
			.rstr(e.getRstr())
			.mdmg(e.getMdmg())
			.prayer(e.getPrayer())
			.aspeed(e.getAspeed())
			.build();
	}

	private static void addIds(Set<Integer> out, Map<String, Set<Integer>> allIds, LoadoutCalculator.Pick pick)
	{
		out.add(pick.getItemId());
		Set<Integer> same = allIds.get(pick.getName().toLowerCase(Locale.ROOT));
		if (same != null)
		{
			out.addAll(same);
		}
		// Other doses of a potion, e.g. "Prayer potion(4)" and "Prayer potion(3)"
		String base = pick.getName().toLowerCase(Locale.ROOT).replaceAll("\\(\\d\\)$", "");
		if (!base.equals(pick.getName().toLowerCase(Locale.ROOT)))
		{
			for (Map.Entry<String, Set<Integer>> e : allIds.entrySet())
			{
				if (e.getKey().startsWith(base + "(") && e.getKey().matches(".*\\(\\d\\)$"))
				{
					out.addAll(e.getValue());
				}
			}
		}
	}

	private void addOwned(Map<String, LoadoutCalculator.Pick> owned, Map<String, Set<Integer>> allIds, int[] ids)
	{
		for (int id : ids)
		{
			if (id <= 0)
			{
				continue;
			}
			ItemComposition comp = itemManager.getItemComposition(id);
			if (comp.getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			int realId = comp.getNote() != -1 ? comp.getLinkedNoteId() : id;
			String name = comp.getName();
			if (name != null)
			{
				String lower = name.toLowerCase(Locale.ROOT);
				owned.putIfAbsent(lower, new LoadoutCalculator.Pick(name, realId));
				allIds.computeIfAbsent(lower, k -> new HashSet<>()).add(realId);
			}
		}
	}

	private static int[] itemIds(ItemContainer container)
	{
		if (container == null)
		{
			return new int[0];
		}
		Item[] items = container.getItems();
		int[] ids = new int[items.length];
		for (int i = 0; i < items.length; i++)
		{
			ids[i] = items[i].getId();
		}
		return ids;
	}

	private void saveBankToProfile()
	{
		StringBuilder sb = new StringBuilder();
		for (int id : bankItemIds)
		{
			if (id > 0)
			{
				if (sb.length() > 0)
				{
					sb.append(',');
				}
				sb.append(id);
			}
		}
		savingBank = true;
		try
		{
			configManager.setRSProfileConfiguration(SlayQueenConfig.GROUP, BANK_KEY, sb.toString());
		}
		finally
		{
			savingBank = false;
		}
	}

	private void loadBankFromProfile()
	{
		needsPrep = "true".equals(configManager.getRSProfileConfiguration(SlayQueenConfig.GROUP, NEEDS_PREP_KEY));
		String saved = configManager.getRSProfileConfiguration(SlayQueenConfig.GROUP, BANK_KEY);
		if (saved == null || saved.isEmpty())
		{
			bankItemIds = new int[0];
			return;
		}
		String[] parts = saved.split(",");
		int[] ids = new int[parts.length];
		for (int i = 0; i < parts.length; i++)
		{
			try
			{
				ids[i] = Integer.parseInt(parts[i].trim());
			}
			catch (NumberFormatException e)
			{
				ids[i] = -1;
			}
		}
		bankItemIds = ids;
	}
}

package com.slayqueen;

import java.util.Collections;
import java.util.List;
import lombok.Data;

/**
 * One slayer task's advice, loaded from tasks.json.
 */
@Data
public class TaskInfo
{
	private String name;
	/** PRAYER_POTIONS, FOOD or BOTH: which of these to bring under supplies. */
	private String supplyType;
	private List<String> styles;
	private String weakness;
	private List<String> tags;
	private List<ItemNeed> requiredItems;
	private List<ItemNeed> recommendedItems;
	private List<ItemNeed> lootItems;
	/** BURST, BARRAGE or CHINCHOMPA when the task is usually stacked and hit with AoE, else null. */
	private String aoe;
	/** YES when AoE is the standard method for the task, OPTIONAL when it's just viable. */
	private String aoeLevel;
	private String aoeWhere;
	private String aoeNote;
	private String cannon;
	private String cannonNote;
	private List<String> notes;

	/** Minimum Slayer level to damage the monster (0 if none). */
	private int slayerLevel;
	/** Quests, skills and diaries needed to reach the task. */
	private List<Requirement> requirements;
	/** Required items that a diary or quest removes the need for. */
	private List<Waiver> waivers;
	/** Konar location name -> extra needs for that location. */
	private java.util.Map<String, AreaInfo> konar;
	/** Advice when the task is from Krystilia (Wilderness only). */
	private WildyInfo wilderness;
	private List<Teleport> teleports;
	/** NONE, POISON or VENOM. */
	private String poison;
	private String poisonNote;
	/** Computed per player by TaskResolver, not loaded from data. */
	private transient List<ItemNeed> supplies;

	@Data
	public static class Requirement
	{
		/** QUEST, SKILL or DIARY. */
		private String type;
		private String quest;
		private String skill;
		private int level;
		private String diary;
		private String tier;
		private String reason;
		private boolean optional;
		/** The quest only needs to be started/partly done (e.g. Troll Stronghold for God Wars). */
		private boolean started;

		String label()
		{
			switch (type == null ? "" : type)
			{
				case "QUEST":
					return pretty(quest);
				case "SKILL":
					return level + " " + pretty(skill);
				case "DIARY":
					return pretty(tier) + " " + pretty(diary) + " diary";
				default:
					return reason == null ? "?" : reason;
			}
		}
	}

	@Data
	public static class Waiver
	{
		private String item;
		private String diary;
		private String tier;
		private String quest;
		private String skill;
		private int level;
		private String reason;
	}

	@Data
	public static class AreaInfo
	{
		private List<ItemNeed> requiredItems;
		private List<ItemNeed> recommendedItems;
		private String cannon;
		private String cannonNote;
		private List<String> notes;
	}

	@Data
	public static class WildyInfo
	{
		private String where;
		private boolean multicombat;
		private String cannon;
		private String cannonNote;
		private String aoe;
		private String aoeNote;
		private List<String> notes;
	}

	@Data
	public static class Teleport
	{
		private String item;
		private List<String> alternatives;
		private String code;
		private String destination;
		private String note;
	}

	/** "CABIN_FEVER" -> "Cabin fever". */
	static String pretty(String constant)
	{
		if (constant == null || constant.isEmpty())
		{
			return "";
		}
		String s = constant.replace('_', ' ').toLowerCase(java.util.Locale.ROOT);
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	@Data
	public static class ItemNeed
	{
		private String name;
		private List<String> alternatives;
		private String reason;

		List<String> allNames()
		{
			if (alternatives == null || alternatives.isEmpty())
			{
				return Collections.singletonList(name);
			}
			List<String> all = new java.util.ArrayList<>();
			all.add(name);
			all.addAll(alternatives);
			return all;
		}
	}

	/**
	 * The weakness only when it matters for the chosen style: stab/slash/crush for melee,
	 * elemental spells for magic. Null otherwise.
	 */
	String weaknessFor(String style)
	{
		if (weakness == null || style == null)
		{
			return null;
		}
		String w = weakness.toLowerCase(java.util.Locale.ROOT);
		boolean melee = w.equals("stab") || w.equals("slash") || w.equals("crush");
		boolean elemental = w.equals("air") || w.equals("water") || w.equals("earth") || w.equals("fire");
		if ("MELEE".equals(style) && melee)
		{
			return "weak to " + w;
		}
		if ("MAGIC".equals(style) && elemental)
		{
			return "weak to " + w + " spells";
		}
		return null;
	}

	/**
	 * Readable weakness: "Air spells" for elemental weaknesses, "Crush" etc. otherwise.
	 */
	String weaknessText()
	{
		if (weakness == null || weakness.isEmpty())
		{
			return null;
		}
		String w = weakness.toLowerCase(java.util.Locale.ROOT);
		String cap = Character.toUpperCase(w.charAt(0)) + w.substring(1);
		boolean elemental = w.equals("air") || w.equals("water") || w.equals("earth") || w.equals("fire");
		return elemental ? cap + " spells" : cap;
	}

	boolean aoeStandard()
	{
		return aoe != null && "YES".equals(aoeLevel);
	}

	/** "Barrage", "Optional (Barrage)" or "No". */
	String aoeText()
	{
		if (aoe == null)
		{
			return "No";
		}
		String method = aoe.charAt(0) + aoe.substring(1).toLowerCase(java.util.Locale.ROOT);
		return aoeStandard() ? method : "Optional (" + method + ")";
	}

	List<String> tagsOrEmpty()
	{
		return tags == null ? Collections.emptyList() : tags;
	}

	static <T> List<T> orEmpty(List<T> list)
	{
		return list == null ? Collections.emptyList() : list;
	}
}

package com.slayqueen;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import lombok.Value;

/**
 * Adapts a task's general advice to the player's situation: Konar's assigned area, a Wilderness
 * (Krystilia) task, diaries that waive items, and requirements the account hasn't met yet.
 * Pure logic so it can be unit tested.
 */
public class TaskResolver
{
	/** What the resolver needs to know about the account. */
	public interface Account
	{
		boolean met(TaskInfo.Requirement requirement);

		int slayerLevel();
	}

	@Value
	public static class Resolved
	{
		TaskInfo task;
		/** Non-optional requirements the account hasn't met, including the Slayer level. */
		List<TaskInfo.Requirement> unmet;
		/** Items the account doesn't need thanks to a diary/quest, with the reason. */
		List<String> waived;
	}

	private static final List<String> ANTIPOISON = Arrays.asList("Antidote++", "Antidote+", "Superantipoison", "Anti-venom+",
		"Anti-venom", "Extended anti-venom+", "Serpentine helm");
	private static final List<String> ANTIVENOM = Arrays.asList("Extended anti-venom+", "Anti-venom", "Serpentine helm",
		"Tanzanite helm", "Magma helm");
	private static final List<String> FOOD = Arrays.asList("Manta ray", "Anglerfish", "Cooked karambwan", "Dark crab",
		"Sea turtle", "Monkfish", "Swordfish", "Lobster", "Tuna", "Salmon");
	private static final List<String> PRAYER = Arrays.asList("Super restore", "Prayer regeneration potion", "Sanfew serum");
	private static final List<String> ANTIFIRE = Arrays.asList("Extended super antifire", "Super antifire potion",
		"Extended antifire", "Antifire potion");

	public Resolved resolve(TaskInfo base, String area, boolean wilderness, Account account)
	{
		TaskInfo t = copy(base);
		List<String> waived = new ArrayList<>();

		if (area != null && base.getKonar() != null)
		{
			TaskInfo.AreaInfo a = findArea(base.getKonar(), area);
			if (a != null)
			{
				addAll(t.getRequiredItems(), a.getRequiredItems());
				addAll(t.getRecommendedItems(), a.getRecommendedItems());
				if (a.getCannon() != null)
				{
					t.setCannon(a.getCannon());
					t.setCannonNote(a.getCannonNote());
				}
				prepend(t.getNotes(), a.getNotes());
			}
		}

		if (wilderness)
		{
			applyWilderness(t, base);
		}

		for (TaskInfo.Waiver w : TaskInfo.orEmpty(base.getWaivers()))
		{
			if (waiverMet(w, account) && removeRequired(t, w.getItem()))
			{
				waived.add(w.getItem() + (w.getReason() == null ? "" : " (" + w.getReason() + ")"));
			}
		}

		addPoisonCure(t);
		t.setSupplies(supplies(t));

		List<TaskInfo.Requirement> unmet = new ArrayList<>();
		if (base.getSlayerLevel() > 0 && account.slayerLevel() < base.getSlayerLevel())
		{
			TaskInfo.Requirement r = new TaskInfo.Requirement();
			r.setType("SKILL");
			r.setSkill("SLAYER");
			r.setLevel(base.getSlayerLevel());
			r.setReason("to damage them");
			unmet.add(r);
		}
		for (TaskInfo.Requirement r : TaskInfo.orEmpty(base.getRequirements()))
		{
			if (!r.isOptional() && !account.met(r))
			{
				unmet.add(r);
			}
		}
		return new Resolved(t, unmet, waived);
	}

	private void applyWilderness(TaskInfo t, TaskInfo base)
	{
		List<String> tags = new ArrayList<>(t.getTags());
		if (!tags.contains("wilderness"))
		{
			tags.add("wilderness");
		}
		t.setTags(tags);

		TaskInfo.WildyInfo w = base.getWilderness();
		List<String> notes = new ArrayList<>();
		notes.add("Krystilia task: kills only count in the Wilderness");
		if (w != null)
		{
			if (w.getWhere() != null)
			{
				notes.add("Go to " + w.getWhere());
			}
			notes.addAll(TaskInfo.orEmpty(w.getNotes()));
			if (w.getCannon() != null)
			{
				t.setCannon(w.getCannon());
				t.setCannonNote(w.getCannonNote());
			}
			// Only Wilderness AoE spots count
			t.setAoe(w.getAoe());
			t.setAoeWhere(w.getAoe() == null ? null : w.getWhere());
			t.setAoeNote(w.getAoeNote());
			t.setAoeLevel(w.getAoe() == null ? null : (base.aoeStandard() ? "YES" : "OPTIONAL"));
		}
		else
		{
			t.setAoe(null);
			t.setAoeWhere(null);
			t.setAoeNote(null);
			t.setAoeLevel(null);
		}
		notes.addAll(t.getNotes());
		t.setNotes(notes);

		if (t.getLootItems().stream().noneMatch(n -> "Looting bag".equals(n.getName())))
		{
			t.getLootItems().add(0, need("Looting bag", "Wilderness: store loot, and less to lose", null));
		}
	}

	private static final java.util.Set<String> GENERIC_WORDS = new java.util.HashSet<>(Arrays.asList(
		"the", "of", "slayer", "cave", "caves", "cavern", "dungeon", "area", "lair", "south", "north", "east", "west"));

	/**
	 * Konar location names differ slightly between the wiki and the game ("Stronghold Slayer Cave" vs
	 * "Stronghold Slayer Dungeon"), so match on the distinctive words only.
	 */
	static TaskInfo.AreaInfo findArea(Map<String, TaskInfo.AreaInfo> areas, String area)
	{
		java.util.Set<String> want = words(area);
		TaskInfo.AreaInfo best = null;
		for (Map.Entry<String, TaskInfo.AreaInfo> e : areas.entrySet())
		{
			if (e.getKey().equalsIgnoreCase(area))
			{
				return e.getValue();
			}
			java.util.Set<String> have = words(e.getKey());
			if (!want.isEmpty() && !have.isEmpty() && (have.containsAll(want) || want.containsAll(have)))
			{
				best = e.getValue();
			}
		}
		return best;
	}

	static java.util.Set<String> words(String name)
	{
		java.util.Set<String> out = new java.util.HashSet<>();
		for (String w : name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9 ]", " ").split("\\s+"))
		{
			if (!w.isEmpty() && !GENERIC_WORDS.contains(w))
			{
				out.add(w.endsWith("s") && w.length() > 4 ? w.substring(0, w.length() - 1) : w);
			}
		}
		return out;
	}

	private static boolean waiverMet(TaskInfo.Waiver w, Account account)
	{
		TaskInfo.Requirement r = new TaskInfo.Requirement();
		if (w.getDiary() != null)
		{
			r.setType("DIARY");
			r.setDiary(w.getDiary());
			r.setTier(w.getTier());
		}
		else if (w.getQuest() != null)
		{
			r.setType("QUEST");
			r.setQuest(w.getQuest());
		}
		else if (w.getSkill() != null)
		{
			r.setType("SKILL");
			r.setSkill(w.getSkill());
			r.setLevel(w.getLevel());
		}
		else
		{
			return false;
		}
		return account.met(r);
	}

	private static boolean removeRequired(TaskInfo t, String item)
	{
		if (item == null)
		{
			return false;
		}
		int before = t.getRequiredItems().size();
		t.getRequiredItems().removeIf(n -> item.equalsIgnoreCase(n.getName())
			|| TaskInfo.orEmpty(n.getAlternatives()).stream().anyMatch(item::equalsIgnoreCase));
		return t.getRequiredItems().size() < before;
	}

	private static void addPoisonCure(TaskInfo t)
	{
		boolean venom = "VENOM".equals(t.getPoison());
		boolean poison = "POISON".equals(t.getPoison());
		if (!venom && !poison)
		{
			return;
		}
		List<String> cures = venom ? ANTIVENOM : ANTIPOISON;
		boolean already = mentions(t.getRequiredItems(), cures) || mentions(t.getRecommendedItems(), cures)
			|| mentions(t.getRecommendedItems(), Arrays.asList("Antipoison", "Anti-venom+", "Antidote++"));
		if (!already)
		{
			String main = venom ? "Anti-venom+" : "Antipoison";
			t.getRecommendedItems().add(0, need(main, venom ? "they envenom you" : "they poison you", cures));
		}
	}

	/**
	 * General supplies for the task: prayer potions or food, antifire for dragons, cannon, and runes for AoE.
	 */
	static List<TaskInfo.ItemNeed> supplies(TaskInfo t)
	{
		List<TaskInfo.ItemNeed> out = new ArrayList<>();
		if ("PRAYER_POTIONS".equals(t.getSupplyType()) || "BOTH".equals(t.getSupplyType()))
		{
			out.add(need("Prayer potion", "to keep praying", PRAYER));
		}
		if (!"PRAYER_POTIONS".equals(t.getSupplyType()))
		{
			out.add(need("Shark", "food", FOOD));
		}
		boolean dragon = t.getTags().contains("dragon");
		if (dragon && !mentions(t.getRequiredItems(), ANTIFIRE) && !mentions(t.getRecommendedItems(), ANTIFIRE))
		{
			out.add(need("Antifire potion", "dragonfire", ANTIFIRE));
		}
		if ("YES".equals(t.getCannon()) || "SOME".equals(t.getCannon()))
		{
			out.add(need("Cannonball", "if you cannon", Arrays.asList("Granite cannonball")));
		}
		if (t.aoeStandard() && !"CHINCHOMPA".equals(t.getAoe()))
		{
			out.add(need("Rune pouch", "for Ancient Magicks runes", Arrays.asList("Divine rune pouch")));
			out.add(need("Blood rune", "Barrage/Burst runes (with death and water runes)", null));
		}
		return out;
	}

	private static boolean mentions(List<TaskInfo.ItemNeed> needs, List<String> names)
	{
		for (TaskInfo.ItemNeed n : TaskInfo.orEmpty(needs))
		{
			for (String name : n.allNames())
			{
				for (String candidate : names)
				{
					if (name.equalsIgnoreCase(candidate))
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	private static TaskInfo.ItemNeed need(String name, String reason, List<String> alternatives)
	{
		TaskInfo.ItemNeed n = new TaskInfo.ItemNeed();
		n.setName(name);
		n.setReason(reason);
		n.setAlternatives(alternatives == null ? new ArrayList<>() : new ArrayList<>(alternatives));
		return n;
	}

	private static void addAll(List<TaskInfo.ItemNeed> into, List<TaskInfo.ItemNeed> extra)
	{
		for (TaskInfo.ItemNeed n : TaskInfo.orEmpty(extra))
		{
			if (into.stream().noneMatch(x -> x.getName().equalsIgnoreCase(n.getName())))
			{
				into.add(n);
			}
		}
	}

	private static void prepend(List<String> into, List<String> extra)
	{
		into.addAll(0, TaskInfo.orEmpty(extra));
	}

	/**
	 * Copy with fresh lists, so resolving never changes the loaded data.
	 */
	static TaskInfo copy(TaskInfo b)
	{
		TaskInfo t = new TaskInfo();
		t.setName(b.getName());
		t.setSupplyType(b.getSupplyType());
		t.setStyles(b.getStyles());
		t.setWeakness(b.getWeakness());
		t.setTags(new ArrayList<>(TaskInfo.orEmpty(b.getTags())));
		t.setRequiredItems(new ArrayList<>(TaskInfo.orEmpty(b.getRequiredItems())));
		t.setRecommendedItems(new ArrayList<>(TaskInfo.orEmpty(b.getRecommendedItems())));
		t.setLootItems(new ArrayList<>(TaskInfo.orEmpty(b.getLootItems())));
		t.setAoe(b.getAoe());
		t.setAoeLevel(b.getAoeLevel());
		t.setAoeWhere(b.getAoeWhere());
		t.setAoeNote(b.getAoeNote());
		t.setCannon(b.getCannon());
		t.setCannonNote(b.getCannonNote());
		t.setNotes(new ArrayList<>(TaskInfo.orEmpty(b.getNotes())));
		t.setSlayerLevel(b.getSlayerLevel());
		t.setRequirements(b.getRequirements());
		t.setWaivers(b.getWaivers());
		t.setKonar(b.getKonar());
		t.setWilderness(b.getWilderness());
		t.setTeleports(b.getTeleports());
		t.setPoison(b.getPoison());
		t.setPoisonNote(b.getPoisonNote());
		return t;
	}
}

